[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Aid Alliance — Together We Respond</title>
<meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root {
  --red: oklch(45% 0.2 25);
  --red-hover: oklch(40% 0.22 25);
  --red-light: oklch(92% 0.04 25);
  --navy: oklch(30% 0.07 250);
  --navy-light: oklch(35% 0.07 250);
  --white: oklch(100% 0 0);
  --gray-50: oklch(98% 0.003 250);
  --gray-100: oklch(95% 0.005 250);
  --gray-200: oklch(90% 0.008 250);
  --gray-300: oklch(82% 0.01 250);
  --gray-500: oklch(60% 0.02 250);
  --gray-600: oklch(45% 0.02 250);
  --gray-700: oklch(35% 0.02 250);
  --gray-800: oklch(25% 0.02 250);
  --gray-900: oklch(18% 0.02 250);
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.08);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 48px oklch(0% 0 0 / 0.16);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --font-heading: 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
}

@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url(https://fonts.gstatic.com/s/inter/v18/UcCO3FwrK3iLTeHuS_nVMrMxCp50SjIw2boKoduKmMEVuLyfAZ9hiJ-Ek-_EeA.woff2) format('woff2');
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  line-height: 1.6;
  background: var(--white);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { text-decoration: none; color: inherit; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ─── HEADER ─── */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}

.header.scrolled { box-shadow: var(--shadow-md); }

.header-utility {
  background: var(--navy);
  color: var(--white);
  font-size: 0.8rem;
  padding: 6px 0;
}

.header-utility .container {
  display: flex;
  justify-content: flex-end;
  gap: 20px;
}

.header-utility a {
  color: oklch(85% 0.02 250);
  transition: color var(--transition);
}

.header-utility a:hover { color: var(--white); }

.header-main .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  padding-bottom: 12px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 800;
  font-size: 1.25rem;
  color: var(--navy);
  letter-spacing: -0.02em;
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: var(--red);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.1rem;
  flex-shrink: 0;
}

.nav-desktop { display: flex; align-items: center; gap: 8px; }

.nav-desktop a {
  padding: 8px 14px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius-sm);
  transition: background var(--transition), color var(--transition);
}

.nav-desktop a:hover {
  background: var(--gray-100);
  color: var(--navy);
}

.btn-donate-nav {
  background: var(--red) !important;
  color: var(--white) !important;
  font-weight: 600 !important;
  padding: 10px 22px !important;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition) !important;
}

.btn-donate-nav:hover {
  background: var(--red-hover) !important;
  transform: translateY(-1px);
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  z-index: 1010;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2.5px;
  background: var(--navy);
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition);
}

.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

.mobile-nav {
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  height: 100vh;
  background: var(--white);
  box-shadow: var(--shadow-xl);
  z-index: 1005;
  transition: right var(--transition);
  padding: 80px 24px 24px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mobile-nav.open { right: 0; }

.mobile-nav a {
  padding: 14px 16px;
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}

.mobile-nav a:hover { background: var(--gray-100); }

.mobile-nav .btn-donate-mobile {
  margin-top: 12px;
  background: var(--red);
  color: var(--white);
  text-align: center;
  font-weight: 600;
  padding: 14px;
  border-radius: var(--radius-sm);
}

.mobile-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: oklch(0% 0 0 / 0.4);
  z-index: 1002;
}

.mobile-overlay.active { display: block; }

/* ─── HERO ─── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--navy) 0%, oklch(25% 0.08 240) 100%);
  overflow: hidden;
  margin-top: 0;
  padding-top: 120px;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 80px;
  background: var(--white);
  clip-path: ellipse(55% 100% at 50% 100%);
}

.hero .container {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.hero-content { color: var(--white); }

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: oklch(100% 0 0 / 0.1);
  backdrop-filter: blur(8px);
  border: 1px solid oklch(100% 0 0 / 0.15);
  padding: 8px 16px;
  border-radius: 50px;
  font-size: 0.85rem;
  margin-bottom: 24px;
  font-weight: 500;
}

.hero-badge::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--red);
  animation: pulse-dot 2s ease-in-out infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.3); }
}

.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.2rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 20px;
}

.hero-subtitle {
  font-size: clamp(1rem, 1.8vw, 1.2rem);
  line-height: 1.7;
  color: oklch(85% 0.02 250);
  margin-bottom: 36px;
  max-width: 520px;
}

.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px 32px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
  box-shadow: 0 4px 14px oklch(45% 0.2 25 / 0.4);
}

.btn-primary:hover {
  background: var(--red-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px oklch(45% 0.2 25 / 0.5);
}

.btn-secondary {
  background: oklch(100% 0 0 / 0.12);
  color: var(--white);
  border: 1.5px solid oklch(100% 0 0 / 0.3);
  backdrop-filter: blur(4px);
}

.btn-secondary:hover {
  background: oklch(100% 0 0 / 0.2);
  transform: translateY(-2px);
}

.hero-image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/3;
  background: oklch(35% 0.06 240);
}

.hero-image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: oklch(70% 0.04 250);
  font-size: 0.9rem;
}

.hero-image-placeholder svg { opacity: 0.5; }

/* ─── SECTION SHARED ─── */
.section {
  padding: 100px 0;
}

.section-header {
  text-align: center;
  margin-bottom: 60px;
}

.section-label {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  margin-bottom: 12px;
}

.section-title {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 3.5vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--gray-900);
  margin-bottom: 16px;
  line-height: 1.15;
}

.section-desc {
  font-size: 1.1rem;
  color: var(--gray-600);
  max-width: 640px;
  margin: 0 auto;
  line-height: 1.7;
}

/* ─── MISSION ─── */
.mission { background: var(--white); }

.mission-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.mission-visual {
  position: relative;
  aspect-ratio: 1;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
}

.mission-visual-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  color: var(--gray-500);
  padding: 40px;
  text-align: center;
}

.mission-visual-inner svg { opacity: 0.4; }

.mission-content .section-label { text-align: left; }
.mission-content .section-title { text-align: left; }

.mission-text {
  font-size: 1.05rem;
  color: var(--gray-600);
  line-height: 1.8;
}

.mission-text strong {
  color: var(--gray-800);
  font-weight: 700;
}

.mission-principles {
  display: flex;
  gap: 24px;
  margin-top: 32px;
}

.principle {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--navy);
}

.principle-icon {
  width: 36px;
  height: 36px;
  background: var(--red-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

/* ─── IMPACT STATS ─── */
.impact {
  background: var(--navy);
  color: var(--white);
  position: relative;
  overflow: hidden;
}

.impact::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: oklch(35% 0.08 250);
  opacity: 0.3;
}

.impact .section-label { color: oklch(75% 0.15 25); }
.impact .section-title { color: var(--white); }
.impact .section-desc { color: oklch(75% 0.03 250); }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  position: relative;
  z-index: 1;
}

.stat-card {
  text-align: center;
  padding: 40px 20px;
  border-radius: var(--radius-md);
  background: oklch(100% 0 0 / 0.06);
  border: 1px solid oklch(100% 0 0 / 0.08);
  backdrop-filter: blur(8px);
  transition: transform var(--transition), background var(--transition);
}

.stat-card:hover {
  transform: translateY(-4px);
  background: oklch(100% 0 0 / 0.1);
}

.stat-icon {
  width: 52px;
  height: 52px;
  margin: 0 auto 20px;
  background: var(--red);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.stat-number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 3.5vw, 2.8rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 0.9rem;
  color: oklch(75% 0.03 250);
  font-weight: 500;
}

.impact-footnote {
  text-align: center;
  margin-top: 48px;
  font-size: 0.95rem;
  color: oklch(70% 0.03 250);
  position: relative;
  z-index: 1;
}

/* ─── PROGRAMS ─── */
.programs { background: var(--gray-50); }

.accordion { max-width: 800px; margin: 0 auto; }

.accordion-item {
  background: var(--white);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  border: 1px solid var(--gray-200);
  overflow: hidden;
  transition: box-shadow var(--transition);
}

.accordion-item:hover { box-shadow: var(--shadow-sm); }

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 24px;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--gray-800);
  text-align: left;
  transition: background var(--transition);
}

.accordion-trigger:hover { background: var(--gray-50); }

.accordion-icon-wrap {
  width: 42px;
  height: 42px;
  background: var(--red-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background var(--transition);
}

.accordion-item.active .accordion-icon-wrap {
  background: var(--red);
}

.accordion-item.active .accordion-icon-wrap svg path {
  stroke: var(--white);
}

.accordion-chevron {
  margin-left: auto;
  transition: transform var(--transition);
  color: var(--gray-500);
  flex-shrink: 0;
}

.accordion-item.active .accordion-chevron { transform: rotate(180deg); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-body-inner {
  padding: 0 24px 24px 82px;
  color: var(--gray-600);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ─── GET INVOLVED ─── */
.get-involved { background: var(--white); }

.involve-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

.involve-card {
  padding: 40px 32px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  background: var(--white);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.involve-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.involve-icon {
  width: 56px;
  height: 56px;
  background: var(--red-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}

.involve-card h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 12px;
}

.involve-card p {
  color: var(--gray-600);
  font-size: 0.95rem;
  line-height: 1.7;
  margin-bottom: 24px;
  flex: 1;
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--red);
  border: 2px solid var(--red);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  align-self: flex-start;
}

.btn-outline:hover {
  background: var(--red);
  color: var(--white);
}

/* ─── NEWS CAROUSEL ─── */
.news { background: var(--gray-50); }

.carousel-wrapper { position: relative; }

.carousel-track {
  display: flex;
  gap: 24px;
  overflow: hidden;
}

.news-card {
  min-width: calc(33.333% - 16px);
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  overflow: hidden;
  transition: all var(--transition);
  flex-shrink: 0;
}

.news-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.news-card-image {
  height: 180px;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-500);
  font-size: 0.85rem;
  position: relative;
  overflow: hidden;
}

.news-card-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, oklch(0% 0 0 / 0.05) 100%);
}

.news-card-body { padding: 24px; }

.news-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--red);
  margin-bottom: 10px;
}

.news-card-body h3 {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 10px;
  line-height: 1.3;
}

.news-card-body p {
  color: var(--gray-600);
  font-size: 0.9rem;
  line-height: 1.6;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 36px;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  transition: all var(--transition);
}

.carousel-btn:hover {
  border-color: var(--red);
  color: var(--red);
  background: var(--red-light);
}

.carousel-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.carousel-btn:disabled:hover {
  border-color: var(--gray-300);
  color: var(--gray-600);
  background: none;
}

.carousel-dots {
  display: flex;
  align-items: center;
  gap: 8px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--transition);
  padding: 0;
}

.carousel-dot.active {
  background: var(--red);
  width: 28px;
  border-radius: 5px;
}

/* ─── DONATE CTA ─── */
.donate-cta {
  background: linear-gradient(135deg, var(--red) 0%, oklch(40% 0.22 15) 100%);
  color: var(--white);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.donate-cta::before {
  content: '';
  position: absolute;
  top: -30%;
  left: -10%;
  width: 500px;
  height: 500px;
  border-radius: 50%;
  background: oklch(100% 0 0 / 0.04);
}

.donate-cta::after {
  content: '';
  position: absolute;
  bottom: -20%;
  right: -10%;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: oklch(100% 0 0 / 0.04);
}

.donate-cta .container { position: relative; z-index: 1; }

.donate-cta .section-label { color: oklch(90% 0.05 25); }
.donate-cta .section-title { color: var(--white); }
.donate-cta .section-desc { color: oklch(90% 0.03 25); }

.efficiency-badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: oklch(100% 0 0 / 0.15);
  padding: 12px 24px;
  border-radius: 50px;
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 32px;
  backdrop-filter: blur(8px);
}

.donate-amounts {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}

.amount-chip {
  padding: 14px 28px;
  border-radius: var(--radius-sm);
  background: oklch(100% 0 0 / 0.12);
  color: var(--white);
  font-weight: 700;
  font-size: 1.1rem;
  border: 2px solid oklch(100% 0 0 / 0.2);
  transition: all var(--transition);
}

.amount-chip:hover, .amount-chip.selected {
  background: var(--white);
  color: var(--red);
  border-color: var(--white);
}

.btn-donate-large {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--white);
  color: var(--red);
  padding: 18px 48px;
  font-size: 1.15rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  box-shadow: 0 4px 20px oklch(0% 0 0 / 0.2);
}

.btn-donate-large:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px oklch(0% 0 0 / 0.3);
}

/* ─── FOOTER ─── */
.footer {
  background: var(--gray-900);
  color: oklch(70% 0.02 250);
  padding: 72px 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid oklch(30% 0.02 250);
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.7;
  margin-top: 16px;
  color: oklch(60% 0.02 250);
}

.footer-social {
  display: flex;
  gap: 12px;
  margin-top: 24px;
}

.social-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: oklch(25% 0.02 250);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition);
  color: oklch(70% 0.02 250);
}

.social-icon:hover {
  background: var(--red);
  color: var(--white);
}

.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--white);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  font-size: 0.9rem;
  padding: 5px 0;
  color: oklch(60% 0.02 250);
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 0.8rem;
  color: oklch(50% 0.02 250);
}

/* ─── DONATION MODAL ─── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: oklch(0% 0 0 / 0.6);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition), visibility var(--transition);
  backdrop-filter: blur(4px);
}

.modal-overlay.active {
  opacity: 1;
  visibility: visible;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: var(--shadow-xl);
  transform: translateY(20px) scale(0.97);
  transition: transform var(--transition);
}

.modal-overlay.active .modal {
  transform: translateY(0) scale(1);
}

.modal-header {
  padding: 28px 28px 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.modal-header h2 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gray-900);
}

.modal-close {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-500);
  transition: background var(--transition);
  flex-shrink: 0;
}

.modal-close:hover { background: var(--gray-100); }

.modal-body { padding: 24px 28px 28px; }

.modal-subtitle {
  color: var(--gray-600);
  font-size: 0.95rem;
  margin-bottom: 28px;
  line-height: 1.6;
}

.donation-type-toggle {
  display: flex;
  background: var(--gray-100);
  border-radius: var(--radius-sm);
  padding: 4px;
  margin-bottom: 24px;
}

.donation-type-btn {
  flex: 1;
  padding: 10px;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: 4px;
  color: var(--gray-600);
  transition: all var(--transition);
  text-align: center;
}

.donation-type-btn.active {
  background: var(--white);
  color: var(--gray-900);
  box-shadow: var(--shadow-sm);
}

.modal-amounts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 20px;
}

.modal-amount-btn {
  padding: 16px 12px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--gray-700);
  transition: all var(--transition);
  text-align: center;
}

.modal-amount-btn:hover {
  border-color: var(--red);
  color: var(--red);
}

.modal-amount-btn.selected {
  border-color: var(--red);
  background: var(--red-light);
  color: var(--red);
}

.modal-amount-btn small {
  display: block;
  font-size: 0.7rem;
  font-weight: 500;
  color: var(--gray-500);
  margin-top: 4px;
}

.modal-amount-btn.selected small { color: var(--red); }

.custom-amount {
  position: relative;
  margin-bottom: 24px;
}

.custom-amount label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--gray-700);
  margin-bottom: 8px;
}

.custom-amount input {
  width: 100%;
  padding: 14px 14px 14px 36px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  font-size: 1.1rem;
  font-weight: 600;
  font-family: inherit;
  transition: border-color var(--transition);
}

.custom-amount input:focus {
  outline: none;
  border-color: var(--red);
}

.custom-amount .currency-symbol {
  position: absolute;
  bottom: 16px;
  left: 14px;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--gray-500);
}

.modal-impact {
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  padding: 14px 18px;
  margin-bottom: 24px;
  font-size: 0.9rem;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: 10px;
}

.modal-impact svg { flex-shrink: 0; }

.btn-modal-donate {
  width: 100%;
  padding: 16px;
  background: var(--red);
  color: var(--white);
  font-size: 1.1rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}

.btn-modal-donate:hover { background: var(--red-hover); }

.modal-footer-note {
  text-align: center;
  margin-top: 16px;
  font-size: 0.8rem;
  color: var(--gray-500);
}

/* ─── ANIMATIONS ─── */
.fade-in {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .involve-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
  .news-card { min-width: calc(50% - 12px); }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .hamburger { display: flex; }

  .header-utility { font-size: 0.75rem; }
  .header-utility .container { gap: 14px; }

  .hero { min-height: auto; padding: 120px 0 80px; }
  .hero .container { grid-template-columns: 1fr; gap: 40px; }
  .hero-image { max-height: 280px; }

  .section { padding: 64px 0; }

  .mission-grid { grid-template-columns: 1fr; gap: 40px; }
  .mission-visual { max-height: 300px; }

  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .stat-card { padding: 28px 16px; }
  .stat-number { font-size: 1.8rem; }

  .involve-grid { grid-template-columns: 1fr; }
  .involve-card { padding: 28px 24px; }

  .news-card { min-width: 85%; }

  .donate-amounts { gap: 10px; }
  .amount-chip { padding: 12px 20px; font-size: 1rem; }

  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }

  .mission-principles { flex-direction: column; gap: 16px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .hero h1 { font-size: 1.9rem; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; }
  .stats-grid { grid-template-columns: 1fr; }
  .modal-amounts { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
}
</style>
