<script>
(function() {
  'use strict';

  // ─── HEADER SCROLL ───
  const header = document.getElementById('header');
  let lastScroll = 0;
  window.addEventListener('scroll', function() {
    header.classList.toggle('scrolled', window.scrollY > 20);
  }, { passive: true });

  // ─── MOBILE MENU ───
  const hamburger = document.getElementById('hamburger');
  const mobileNav = document.getElementById('mobile-nav');
  const overlay = document.getElementById('mobile-overlay');

  function toggleMobile(open) {
    const isOpen = open !== undefined ? open : !mobileNav.classList.contains('open');
    mobileNav.classList.toggle('open', isOpen);
    overlay.classList.toggle('active', isOpen);
    hamburger.classList.toggle('active', isOpen);
    hamburger.setAttribute('aria-expanded', isOpen);
    document.body.style.overflow = isOpen ? 'hidden' : '';
  }

  hamburger.addEventListener('click', function() { toggleMobile(); });
  overlay.addEventListener('click', function() { toggleMobile(false); });

  mobileNav.querySelectorAll('a').forEach(function(a) {
    a.addEventListener('click', function() { toggleMobile(false); });
  });

  // ─── DONATION MODAL ───
  var modal = document.getElementById('donate-modal');
  var modalClose = document.getElementById('modal-close');
  var selectedAmount = 50;

  var impacts = {
    25: 'Your $25 gift provides 5 emergency blankets for displaced families.',
    50: 'Your $50 gift supplies a family with food and water for one week.',
    100: 'Your $100 gift funds emergency shelter materials for a household.',
    250: 'Your $250 gift equips a volunteer with disaster response training.'
  };

  function openModal() {
    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeModal() {
    modal.classList.remove('active');
    document.body.style.overflow = '';
  }

  document.querySelectorAll('[data-donate-trigger]').forEach(function(btn) {
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      openModal();
    });
  });

  modalClose.addEventListener('click', closeModal);
  modal.addEventListener('click', function(e) {
    if (e.target === modal) closeModal();
  });

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && modal.classList.contains('active')) closeModal();
  });

  function updateModalAmount(amount) {
    selectedAmount = amount;
    document.querySelectorAll('.modal-amount-btn').forEach(function(b) {
      b.classList.toggle('selected', parseInt(b.dataset.modalAmount) === amount);
    });
    var impactEl = document.getElementById('modal-impact').querySelector('span');
    impactEl.textContent = impacts[amount] || 'Every dollar counts toward saving lives.';
    document.getElementById('btn-complete-donation').textContent = 'Donate $' + amount + ' Now';
    document.getElementById('custom-amount-input').value = '';
  }

  document.querySelectorAll('.modal-amount-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      updateModalAmount(parseInt(this.dataset.modalAmount));
    });
  });

  document.getElementById('custom-amount-input').addEventListener('input', function() {
    var val = parseInt(this.value);
    if (val > 0) {
      selectedAmount = val;
      document.querySelectorAll('.modal-amount-btn').forEach(function(b) { b.classList.remove('selected'); });
      var impactEl = document.getElementById('modal-impact').querySelector('span');
      impactEl.textContent = impacts[val] || 'Your $' + val + ' gift helps us respond to disasters and support communities in crisis.';
      document.getElementById('btn-complete-donation').textContent = 'Donate $' + val + ' Now';
    }
  });

  document.querySelectorAll('.donation-type-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      document.querySelectorAll('.donation-type-btn').forEach(function(b) { b.classList.remove('active'); });
      this.classList.add('active');
      var isMonthly = this.dataset.type === 'monthly';
      document.getElementById('btn-complete-donation').textContent =
        (isMonthly ? 'Donate $' + selectedAmount + '/month' : 'Donate $' + selectedAmount + ' Now');
    });
  });

  document.getElementById('btn-complete-donation').addEventListener('click', function() {
    var type = document.querySelector('.donation-type-btn.active').dataset.type;
    alert('Thank you for your ' + (type === 'monthly' ? 'monthly ' : '') + '$' + selectedAmount + ' donation! In a production environment, you would be redirected to a secure payment processor.');
    closeModal();
  });

  // CTA section amount chips
  document.querySelectorAll('.amount-chip').forEach(function(chip) {
    chip.addEventListener('click', function() {
      document.querySelectorAll('.amount-chip').forEach(function(c) { c.classList.remove('selected'); });
      this.classList.add('selected');
      selectedAmount = parseInt(this.dataset.amount);
    });
  });

  // ─── ACCORDION ───
  document.querySelectorAll('.accordion-trigger').forEach(function(trigger) {
    trigger.addEventListener('click', function() {
      var item = this.parentElement;
      var isActive = item.classList.contains('active');
      var body = item.querySelector('.accordion-body');

      // Close all
      document.querySelectorAll('.accordion-item').forEach(function(i) {
        i.classList.remove('active');
        i.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
        i.querySelector('.accordion-body').style.maxHeight = null;
      });

      if (!isActive) {
        item.classList.add('active');
        this.setAttribute('aria-expanded', 'true');
        body.style.maxHeight = body.scrollHeight + 'px';
      }
    });
  });

  // ─── NEWS CAROUSEL ───
  var track = document.getElementById('carousel-track');
  var cards = track.querySelectorAll('.news-card');
  var prevBtn = document.getElementById('carousel-prev');
  var nextBtn = document.getElementById('carousel-next');
